#[derive(Clone)]
pub(crate) enum JThrow {
    AbortException(J<AbortException>),
    LevelException(J<LevelException>),
    LookaheadSuccess(J<LookaheadSuccess>),
    ParseException(J<ParseExceptionObj>),
    TokenMgrError(J<TokenMgrError>),
    Extern(ExternThrowable),
}

impl JThrow {
    /// Whether this is an instance of the library class `class`.
    pub(crate) fn is_a(&self, class: &str) -> bool {
        match self {
            JThrow::AbortException(_) => ["Exception", "Throwable"].contains(&class),
            JThrow::LevelException(_) => ["Exception", "Throwable"].contains(&class),
            JThrow::LookaheadSuccess(_) => ["Error", "Throwable"].contains(&class),
            JThrow::ParseException(_) => ["Exception", "Throwable"].contains(&class),
            JThrow::TokenMgrError(_) => ["Error", "Throwable"].contains(&class),
            JThrow::Extern(e) => extern_is_a(e.class, class),
        }
    }

    pub(crate) fn getMessage(&self) -> JResult<JStr> {
        match self {
            JThrow::AbortException(e) => Ok(e.jread(|o| o.detailMessage.clone())),
            JThrow::LevelException(e) => Ok(e.jread(|o| o.detailMessage.clone())),
            JThrow::LookaheadSuccess(e) => Ok(e.jread(|o| o.detailMessage.clone())),
            JThrow::ParseException(e) => e.getMessage(),
            JThrow::TokenMgrError(e) => e.getMessage(),
            JThrow::Extern(e) => Ok(e.message.clone()),
        }
    }
}

impl std::fmt::Debug for JThrow {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            JThrow::AbortException(_) => f.write_str("AbortException"),
            JThrow::LevelException(_) => f.write_str("LevelException"),
            JThrow::LookaheadSuccess(_) => f.write_str("LookaheadSuccess"),
            JThrow::ParseException(_) => f.write_str("ParseException"),
            JThrow::TokenMgrError(_) => f.write_str("TokenMgrError"),
            JThrow::Extern(e) => f.write_str(e.class),
        }
    }
}

/// The library exception hierarchy, as far as `catch` needs it.
fn extern_is_a(class: &str, target: &str) -> bool {
    match class {
        "Throwable" => ["Throwable"].contains(&target),
        "Exception" => ["Exception", "Throwable"].contains(&target),
        "Error" => ["Error", "Throwable"].contains(&target),
        "RuntimeException" => ["RuntimeException", "Exception", "Throwable"].contains(&target),
        "IllegalArgumentException" => ["IllegalArgumentException", "RuntimeException", "Exception", "Throwable"].contains(&target),
        "NumberFormatException" => ["NumberFormatException", "IllegalArgumentException", "RuntimeException", "Exception", "Throwable"].contains(&target),
        "IllegalStateException" => ["IllegalStateException", "RuntimeException", "Exception", "Throwable"].contains(&target),
        "UnsupportedOperationException" => ["UnsupportedOperationException", "RuntimeException", "Exception", "Throwable"].contains(&target),
        "NoSuchElementException" => ["NoSuchElementException", "RuntimeException", "Exception", "Throwable"].contains(&target),
        "IOException" => ["IOException", "Exception", "Throwable"].contains(&target),
        "UnsupportedEncodingException" => ["UnsupportedEncodingException", "IOException", "Exception", "Throwable"].contains(&target),
        "FileNotFoundException" => ["FileNotFoundException", "IOException", "Exception", "Throwable"].contains(&target),
        "WrongInvocationException" => ["WrongInvocationException", "RuntimeException", "Exception", "Throwable"].contains(&target),
        _ => false,
    }
}

/// Forgets every translated class's statics, as a fresh JVM would (a new session).
pub(crate) fn reset_all_statics() {
    TLAplusParserConstants::reset_statics();
    SyntaxTreeConstants::reset_statics();
    TLAplusParserTokenManager::reset_statics();
    SyntaxTreeNode::reset_statics();
    Operator::reset_statics();
    Operators::reset_statics();
    Strings::reset_statics();
    TLAplusParser::reset_statics();
    ASTConstants::reset_statics();
    BuiltInOperators::reset_statics();
    Context::reset_statics();
    FrontEnd::reset_statics();
    Generator::reset_statics();
    LevelConstants::reset_statics();
    SemanticNode::reset_statics();
    StandardModules::reset_statics();
}
